param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'type-shaped-metadata-definition-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}



function Base($name){$list=[object].Assembly.GetType('System.Collections.Generic.List`1');$dict=[object].Assembly.GetType('System.Collections.Generic.Dictionary`2');$nullable=[object].Assembly.GetType('System.Nullable`1');switch($name){'ListD'{return $list};'ListS'{return $list.MakeGenericType([type[]]@([string]))};'ListI'{return $list.MakeGenericType([type[]]@([int]))};'DictD'{return $dict};'DictSI'{return $dict.MakeGenericType([type[]]@([string],[int]))};'NullableD'{return $nullable};'NullableI'{return $nullable.MakeGenericType([type[]]@([int]))};'Pnullable'{return $nullable.GetGenericArguments()[0]};'Plist'{return $list.GetGenericArguments()[0]};default{return [Type]::GetType($name,$true,$false)}}}
function Shaped($type,$shape){switch($shape){'none'{return $type};'sz'{return $type.MakeArrayType()};'md1'{return $type.MakeArrayType(1)};'md2'{return $type.MakeArrayType(2)};'md3'{return $type.MakeArrayType(3)};'jagged'{return $type.MakeArrayType().MakeArrayType()};'ptr'{return $type.MakePointerType()};'ptrptr'{return $type.MakePointerType().MakePointerType()};'byref'{return $type.MakeByRefType()};'arrayptr'{return $type.MakeArrayType().MakePointerType()};'ptrarray'{return $type.MakePointerType().MakeArrayType()}}}
function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$types=[Collections.Generic.List[type]]::new();$diagnostics=[Collections.Generic.List[object]]::new();foreach($base in $plan.bases){$type=Base $base;foreach($shape in $plan.shapes){$value=Shaped $type $shape;$types.Add($value);$diagnostics.Add([ordered]@{index=$diagnostics.Count;base=$base;shape=$shape;token=$value.MetadataToken;module=$value.Module.Name;hasElement=$value.HasElementType})}}
$rows=[Collections.Generic.List[object]]::new();for($left=0;$left -lt $types.Count;$left++){for($right=0;$right -le $types.Count;$right++){$other=if($right -eq $types.Count){$null}else{$types[$right]};$same=$null;$exception='none';$message=$null;$hResult=0;$param=$null;try{$same=$types[$left].HasSameMetadataDefinitionAs($other)}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};if($errorValue -isnot [ArgumentNullException]){throw};$exception=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;$param=$errorValue.ParamName};$rows.Add([ordered]@{left=$left;right=$right;same=$same;exception=$exception;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param);equal=$types[$left].Equals($other)})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();typeCount=$types.Count;diagnostics=$diagnostics.ToArray();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS shaped metadata: $($rows.Count) pairs"
